void vectorized_s242(int iterations, int LEN_1D, float s1, float s2, float* a, float* b, float* c, float* d)
{
    float s12 = s1 + s2;
    for (int nl = 0; nl < iterations/5; nl++) {
        float tmp[LEN_1D];

        int i = 0;
        int limit = LEN_1D - 7;
        if (limit < 0) limit = 0;

        for (; i < limit; i += 8) {
            tmp[i]   = b[i]   + c[i]   + d[i]   + s12;
            tmp[i+1] = b[i+1] + c[i+1] + d[i+1] + s12;
            tmp[i+2] = b[i+2] + c[i+2] + d[i+2] + s12;
            tmp[i+3] = b[i+3] + c[i+3] + d[i+3] + s12;
            tmp[i+4] = b[i+4] + c[i+4] + d[i+4] + s12;
            tmp[i+5] = b[i+5] + c[i+5] + d[i+5] + s12;
            tmp[i+6] = b[i+6] + c[i+6] + d[i+6] + s12;
            tmp[i+7] = b[i+7] + c[i+7] + d[i+7] + s12;
        }
        for (; i < LEN_1D; i++) {
            tmp[i] = b[i] + c[i] + d[i] + s12;
        }

        /* The original loop starts at i=1: a[i] = a[i-1] + s1+s2+b[i]+c[i]+d[i]
           So a[0] is never written by the inner loop; only a[1..LEN_1D-1] are updated.
           a[1] = a[0] + tmp[1], a[2] = a[1] + tmp[2], etc.
           We must NOT touch a[0], and start the prefix sum from a[0]. */
        for (i = 1; i < LEN_1D; i++) {
            a[i] = a[i-1] + tmp[i];
        }
    }
}

void s242_opt(int iterations, int LEN_1D, float s1, float s2, float* a, float* b, float* c, float* d)
{
    float s12 = s1 + s2;
    for (int nl = 0; nl < iterations/5; nl++) {
        // Compute prefix sums of (b[i] + c[i] + d[i] + s12) independently
        // Then reconstruct a[i] = a[0] + sum_{k=1}^{i} (s12 + b[k] + c[k] + d[k])
        // Step 1: compute increments into a temporary scan array
        // We use b as a conceptual helper but keep a separate temp array approach
        // Instead: precompute cumulative sum in a temp buffer, then add a[0]
        float temp[LEN_1D];
        // Step 1: vectorizable - compute per-element increments
        for (int i = 1; i < LEN_1D; ++i) {
            temp[i] = s12 + b[i] + c[i] + d[i];
        }
        // Step 2: prefix sum (carry dependency isolated here)
        for (int i = 2; i < LEN_1D; ++i) {
            temp[i] = temp[i] + temp[i - 1];
        }
        // Step 3: vectorizable - write back results
        float a0 = a[0];
        for (int i = 1; i < LEN_1D; ++i) {
            a[i] = a0 + temp[i];
        }
    }
}
